// Тикет #6a86f7d99a8f «עיצוב מוקאפ: תהילים — רשימת פרקים וקטעים» (S-24), проверен 07.10.2026 → עבר QA (session.json: «S-24 AC3-6 ✅, реджект 27.09 ✅»).
// Опора: реджект 27.09 п.2 (фильтр по дням: «כל הימים», א׳–ו׳, שבת); комментарий программиста 28.09 — принятое деление
// «א׳ 1–29 … שבת 120–150» (бриф: א׳ 1–29, ב׳ 30–50, ג׳ 51–72, ד׳ 73–89, ה׳ 90–106, ו׳ 107–119, שבת 120–150).
// Скрины: d99a8f-1-site-390 (чипы дней), d99a8f-3-day-shabbat («שבת: פרקים …, לפי החלוקה המקובלת של ספר תהילים לימות השבוע.», первый ק״כ).
// Дополняет specs/tehilim/th-02 (там — только שבת и א׳): здесь границы каждого дня. Строки тем не проверяем (нет в документации).
import { expect } from '@wdio/globals';
import { byText, byTextContains, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { hebNum, searchField, scrollUpToText } from '../_lib/app-0710.ts';

const DAYS: Array<[day: string, first: number, last: number]> = [
  ['א׳', 1, 29], ['ב׳', 30, 50], ['ג׳', 51, 72], ['ד׳', 73, 89], ['ה׳', 90, 106], ['ו׳', 107, 119], ['שבת', 120, 150],
];
const DIVISION_NOTE = 'לפי החלוקה המקובלת של ספר תהילים לימות השבוע';

describe('Список תהילים: фильтр по дням', () => {
  afterEach(async () => {
    const all = await byText('כל הימים');
    if (await all.isDisplayed().catch(() => false)) await all.click();
    await toHome();
  });

  it('TL-01 Каждый день недели показывает свои פרקים (א׳ 1–29 … שבת 120–150), «כל הימים» — весь список #6a86f7d99a8f @prod-safe', async () => {
    await goTab('תהילים');
    await (await searchField()).waitForDisplayed({ timeout: 20000 });
    await expectVisibleText('כל הימים');

    for (const [day, first, last] of DAYS) {
      await (await scrollUpToText(day, 12)).click();   // после прокрутки списка чипы могли уйти вверх
      await expect(byTextContains(DIVISION_NOTE)).toBeDisplayed({ message: `${day}: нет пояснения о делении` });
      // Первый פרק дня. Для א׳ метка «א׳» совпадает с чипом — сверяем по первым словам פרק א׳.
      if (first === 1) await expectVisibleText('אשרי האיש אשר');
      else {
        await expect(byText(hebNum(first))).toBeDisplayed({ message: `${day}: первый פרק ${hebNum(first)}` });
        await expect(byText(hebNum(first - 1))).not.toBeDisplayed();
      }
      // Последний פרק дня есть, следующего за ним — нет.
      await scrollToText(hebNum(last), 15);
      await expect(byText(hebNum(last))).toBeDisplayed({ message: `${day}: последний פרק ${hebNum(last)}` });
      if (last < 150) await expect(byText(hebNum(last + 1))).not.toBeDisplayed();
    }

    // «כל הימים» — снова с פרק א׳, пояснения о делении нет.
    await (await scrollUpToText('כל הימים', 12)).click();
    await expectVisibleText('אשרי האיש אשר');
    await expect(byTextContains(DIVISION_NOTE)).not.toBeDisplayed();
  });
});
